from pathlib import Path
base=Path(__file__).parent
css='''*{box-sizing:border-box}body{margin:0;font-family:"Segoe UI","Malgun Gothic",sans-serif;color:var(--ink);background:var(--bg)}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #d98a43;outline-offset:4px}header{display:flex;justify-content:space-between;align-items:center;padding:26px 5%;border-bottom:1px solid var(--line)}.brand{font-weight:800;text-decoration:none;letter-spacing:-1px;font-size:22px}nav{display:flex;gap:22px;font-size:13px}nav a{text-decoration:none}main{max-width:1280px;margin:auto;padding:0 5%}h1{font-size:clamp(46px,7.5vw,100px);line-height:1.12;letter-spacing:-.065em;font-weight:600;margin:25px 0}h2{font-size:30px;letter-spacing:-1px}p{line-height:1.8}.eyebrow{font-size:11px;letter-spacing:3px;text-transform:uppercase}.hero{padding:70px 0 60px}.muted{color:var(--muted)}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.pill,button{border:1px solid var(--line);border-radius:30px;background:transparent;color:inherit;padding:11px 20px}.active,.primary{background:var(--ink);color:var(--bg)}input,textarea,select{padding:13px 16px;background:transparent;border:1px solid var(--line);border-radius:8px;color:inherit}textarea{width:100%;min-height:120px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.card{padding-bottom:24px;border-bottom:1px solid var(--line)}.art{height:260px;position:relative;overflow:hidden;border-radius:3px}.card h3{font-size:23px;margin:17px 0 8px}.small{font-size:12px}footer{margin-top:80px;padding:30px 5%;border-top:1px solid var(--line);display:flex;justify-content:space-between;font-size:12px}.empty{padding:50px;text-align:center}.panel{border:1px solid var(--line);border-radius:22px;padding:30px}dialog{max-width:550px;width:90%;border:1px solid var(--line);background:var(--bg);color:var(--ink);padding:30px;border-radius:18px}dialog::backdrop{background:#0008}[hidden]{display:none!important}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.hero{padding:45px 0}.split{grid-template-columns:1fr!important}nav{gap:12px}.art{height:220px}}@media(max-width:520px){.grid{grid-template-columns:1fr}header{align-items:flex-start;gap:12px}nav{flex-wrap:wrap;font-size:11px}h1{font-size:49px}.panel{padding:20px}footer{gap:20px}}'''
def save(slug,title,theme,body,js):
 html='<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+title+' — 일상의 영감과 나만의 시간을 위한 공간"><title>'+title+'</title><style>'+css+theme+'</style></head><body>'+body+'<script>'+js+'</script></body></html>'
 (base/slug/'dist/index.html').write_text(html,encoding='utf-8')
save('taste-pieces','취향의 조각', ''' :root{--bg:#f5f2e9;--ink:#254c3a;--line:#c8cec1;--muted:#717c6d}.hero{position:relative}.hero:after{content:'✳';position:absolute;right:4%;top:50px;font-size:190px;color:#b6bf92}.art:before,.art:after{content:'';position:absolute}.book{background:#cfb67d}.book:before{width:115px;height:175px;background:#385343;transform:rotate(-12deg);left:30%;top:40px;box-shadow:10px 8px #eee5d0}.book:after{content:'SLOW\\A DAYS';white-space:pre;color:#f1e6c9;left:38%;top:85px;font-size:22px;transform:rotate(-12deg)}.place{background:linear-gradient(140deg,#b5c5bb,#d7d1b5)}.place:before{width:160px;height:200px;border-radius:100px 100px 0 0;background:#496856;left:27%;top:40px;border:15px solid #e4d8bb}.place:after{width:110px;height:65px;border-radius:50%;background:#ede7d9;left:38%;bottom:0;box-shadow:0 -10px #b39d7b}.music{background:#ca7e62}.music:before{width:190px;height:190px;border-radius:50%;background:repeating-radial-gradient(#292e2a 0 3px,#41433a 4px 5px);top:35px;left:22%}.music:after{width:50px;height:50px;border:18px solid #dfbb82;background:#222;border-radius:50%;top:105px;left:calc(22% + 70px)}@media(max-width:800px){.hero:after{display:none}}''', '''<header><a class="brand" href="#">취향의 조각<span style="color:#94a16b"> ✳</span></a><nav><a href="#collection">컬렉션</a><a href="#memo">나의 메모</a></nav></header><main><section class="hero"><div class="eyebrow">A personal collection · Vol. 01</div><h1>좋아하는 것들이<br>나를 이루니까.</h1><p class="muted">마음에 남은 장소, 오래 듣는 음악, 다시 펼치는 책.<br>흩어진 취향을 하나씩 모아두는 작은 서랍.</p></section><section id="collection"><div class="row between"><h2>수집한 조각들 <sup class="small">06</sup></h2><input id="search" aria-label="컬렉션 검색" placeholder="어떤 조각을 찾나요?"></div><div class="row" id="filters" style="margin:10px 0 30px"><button class="active" data-cat="전체">전체</button><button data-cat="장소">장소</button><button data-cat="음악">음악</button><button data-cat="책">책</button><button data-cat="저장">♡ 저장한 조각</button></div><div class="grid" id="cards"></div><p id="empty" class="empty" hidden>아직 일치하는 조각이 없어요.</p><p class="small muted">처음 둘러보기 위한 예시 컬렉션입니다. 그래픽은 사이트를 위해 만든 일러스트입니다.</p></section><section id="memo" class="panel" style="margin-top:60px"><div class="eyebrow">A note to myself</div><h2>오늘 발견한 취향은?</h2><textarea id="note" aria-label="나의 취향 메모" placeholder="오늘 마음에 든 것을 적어보세요."></textarea><p class="small muted" id="noteState">메모와 저장한 조각은 이 브라우저에 자동 저장됩니다.</p></section></main><footer><span>취향의 조각 © 2026</span><span>작은 발견을 오래 간직하기.</span></footer>''', '''const data=[['책','느리게 읽는 오후','속도보다 여백이 필요한 날.','book'],['장소','창가의 작은 카페','햇빛이 오래 머무는 자리를 찾아서.','place'],['음악','해질녘의 플레이리스트','오늘의 속도를 조금 낮추는 선율.','music'],['장소','초록을 걷는 시간','익숙한 산책길에서 발견한 새로운 풍경.','place'],['책','문장 수집 노트','다시 읽고 싶은 말들을 한 페이지에.','book'],['음악','비 오는 날의 재즈','창문 밖 소리와 어울리는 리듬.','music']];let saved;try{saved=JSON.parse(localStorage.getItem('taste-saved')||'[]')}catch{saved=[]}let cat='전체';const cards=document.querySelector('#cards');function render(){cards.innerHTML='';data.forEach((d,i)=>{if((cat!=='전체'&&cat!=='저장'&&cat!==d[0])||(cat==='저장'&&!saved.includes(i))||!d.join(' ').includes(document.querySelector('#search').value.trim()))return;const el=document.createElement('article');el.className='card';el.innerHTML=`<div class="art ${d[3]}" role="img" aria-label="${d[0]} 추상 일러스트"></div><div class="row between" style="margin-top:16px"><span class="eyebrow">${d[0]} / 0${i+1}</span><button aria-label="${d[1]} 저장" aria-pressed="${saved.includes(i)}">${saved.includes(i)?'♥':'♡'}</button></div><h3>${d[1]}</h3><p class="muted small">${d[2]}</p>`;el.querySelector('button').onclick=()=>{saved=saved.includes(i)?saved.filter(n=>n!==i):[...saved,i];try{localStorage.setItem('taste-saved',JSON.stringify(saved))}catch{}render()};cards.append(el)});document.querySelector('#empty').hidden=cards.children.length>0}document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(a=>a.classList.toggle('active',a===b));render()});document.querySelector('#search').oninput=render;const note=document.querySelector('#note');try{note.value=localStorage.getItem('taste-note')||''}catch{}note.oninput=()=>{try{localStorage.setItem('taste-note',note.value);document.querySelector('#noteState').textContent='이 브라우저에 저장했어요.'}catch{document.querySelector('#noteState').textContent='현재 브라우저에서는 저장할 수 없어요.'}};render();''')
save('studio-note','Studio Note · 포트폴리오', ''':root{--bg:#f3f1ec;--ink:#20201e;--line:#ceccc4;--muted:#72726c}.hero{padding-bottom:70px}.accent{color:#e35d42}.project{display:block;text-decoration:none}.art{height:350px;padding:30px;display:flex;align-items:center;justify-content:center;transition:transform .3s}.project:hover .art{transform:translateY(-5px)}.poster{background:#e15e43;color:#f6eaca;font-size:70px;line-height:.9;font-weight:900;letter-spacing:-7px}.sphere{background:#c7c9bd}.sphere:after{content:'';width:210px;height:210px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#f8f5e4,#929c7f 55%,#323b2f);box-shadow:35px 45px 35px #6665}.type{background:#282a2b;color:#e8e4d6;font-family:Georgia;font-size:110px}.split{display:grid;grid-template-columns:1fr 1fr;gap:50px}.tag{font-size:11px;border:1px solid var(--line);padding:5px 10px;border-radius:20px}.project{cursor:pointer}.about{border-top:1px solid var(--line);margin-top:70px;padding-top:45px}''', '''<header><a class="brand" href="#">STUDIO NOTE<span class="accent">®</span></a><nav><a href="#work">작업</a><a href="#about">소개</a><a href="#contact">연락</a></nav></header><main><section class="hero"><div class="row between eyebrow"><span>Independent creative portfolio</span><span>Seoul, KR · Demo</span></div><h1>생각을 정리하고,<br><span class="accent">감각을</span> 만듭니다.</h1><div class="row between"><p class="muted">브랜드의 첫인상부터 일상 속 작은 경험까지.<br>명확한 의도와 오래 남는 디자인을 고민합니다.</p><a class="pill" href="#work">선택한 작업 보기 ↘</a></div></section><section id="work"><div class="row between"><h2>Selected work</h2><span class="small muted">콘셉트 프로젝트 / 01 — 03</span></div><div class="grid"><a href="#" class="project card" data-project="0"><div class="art poster">SLOW<br>GROVE.</div><h3>Slow Grove</h3><div class="row"><span class="tag">Brand identity</span><span class="small muted">2026</span></div></a><a href="#" class="project card" data-project="1"><div class="art sphere" role="img" aria-label="자연빛을 담은 구형 오브젝트"></div><h3>Objects of calm</h3><div class="row"><span class="tag">Art direction</span><span class="small muted">2026</span></div></a><a href="#" class="project card" data-project="2"><div class="art type">Aa.</div><h3>Letter / Matter</h3><div class="row"><span class="tag">Editorial design</span><span class="small muted">2026</span></div></a></div></section><section id="about" class="split about"><div><div class="eyebrow">Behind the work</div><h2>좋은 질문에서<br>좋은 디자인이 시작됩니다.</h2></div><div><p>Studio Note는 개인 포트폴리오를 위한 예시 공간입니다. 브랜드 아이덴티티, 아트 디렉션, 편집 디자인의 세 가지 콘셉트 작업을 담았습니다.</p><p class="muted">실제 이름, 경력, 작업물로 바꾸면 나만의 포트폴리오로 사용할 수 있습니다. 여기의 프로젝트는 실적이나 고객 사례를 주장하지 않는 가상 작업입니다.</p></div></section><section id="contact" class="about"><div class="eyebrow">Start a conversation</div><h2 style="font-size:clamp(36px,5vw,65px)">다음 이야기를 함께 써요. ↗</h2><p class="muted">보낼 내용을 아래에 정리하고 텍스트 파일로 내려받으세요.</p><form id="brief"><div class="row"><input name="name" aria-label="이름" placeholder="이름" required><input name="email" type="email" aria-label="이메일" placeholder="이메일" required></div><textarea name="message" aria-label="프로젝트 설명" placeholder="함께하고 싶은 프로젝트를 알려주세요." style="margin:15px 0" required></textarea><button class="primary">문의 초안 내려받기 ↗</button><span id="status" class="small" role="status"></span><p class="small muted">예시 사이트로, 문의는 전송되지 않습니다. 실제 연락처는 아직 등록되지 않았습니다.</p></form></section></main><footer><span>STUDIO NOTE © 2026</span><a href="#">Back to top ↑</a></footer><dialog><button id="close" style="float:right" aria-label="닫기">✕</button><div class="eyebrow">Concept project</div><h2 id="ptitle"></h2><p id="pbody"></p><p class="small muted">포트폴리오 레이아웃을 보여주기 위한 가상 프로젝트입니다.</p></dialog>''', '''const projects=[['Slow Grove','느린 일상의 리듬에서 출발한 가상의 라이프스타일 브랜드입니다. 따뜻한 코랄 컬러와 대담한 타이포그래피로 편안함과 생동감을 함께 표현했습니다.'],['Objects of calm','빛과 재질이 만드는 고요한 순간을 탐구한 아트 디렉션 콘셉트입니다. 절제된 색과 부드러운 구의 형태를 웹 그래픽으로 구현했습니다.'],['Letter / Matter','글자가 이미지가 되는 순간을 위한 편집 디자인 실험입니다. 여백, 대비, 큰 세리프 문자를 중심으로 읽는 경험의 리듬을 구성했습니다.']];const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(a=>a.onclick=e=>{e.preventDefault();const p=projects[+a.dataset.project];document.querySelector('#ptitle').textContent=p[0];document.querySelector('#pbody').textContent=p[1];dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};document.querySelector('#brief').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const text=`프로젝트 문의 초안\\n이름: ${f.get('name')}\\n이메일: ${f.get('email')}\\n\\n${f.get('message')}`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='project-inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent=' 초안을 내려받았습니다.'};''')
save('day-focus','오늘의 몰입', ''':root{--bg:#eeeff5;--ink:#303c67;--line:#cbd0e0;--muted:#7a829d}.split{display:grid;grid-template-columns:1.1fr 1fr;gap:28px}.timer{text-align:center;background:#303c67;color:#f3f2e9;border-radius:25px;padding:38px 25px}.clock{font-size:clamp(70px,9vw,120px);font-variant-numeric:tabular-nums;letter-spacing:-5px;margin:32px 0 8px}.timer button{border-color:#7d89b0}.timer .active{background:#eeeff5;color:#303c67}.timer .primary{background:#dce7ac;color:#303c67}.timer .muted{color:#bfc7e1}.progress{height:4px;background:#58648c;margin:25px 0;border-radius:5px;overflow:hidden}.progress div{height:100%;background:#dce7ac;width:0}.task{display:flex;gap:12px;align-items:center;padding:18px 0;border-bottom:1px solid var(--line)}.task span{flex:1;overflow-wrap:anywhere}.task input{accent-color:#303c67;width:19px;height:19px}.task.done span{text-decoration:line-through;opacity:.5}.task button{padding:4px 9px}.stat{font-size:35px;margin:10px 0}.quote{font-size:22px;margin:45px 0}.hero h1{font-size:clamp(40px,5vw,64px)}''', '''<header><a class="brand" href="#">오늘의 몰입 <span style="color:#97a76b">●</span></a><span id="date" class="small muted"></span></header><main><section class="hero"><div class="eyebrow">One thing at a time</div><h1>조금씩, 분명하게.<br>오늘의 나에게 집중하는 시간.</h1><p class="muted">모든 일을 한 번에 할 필요는 없어요. 지금 할 일 하나면 충분해요.</p></section><div class="split"><section class="timer" aria-label="집중 타이머"><div class="row" style="justify-content:center"><button class="active" data-min="25">집중 25분</button><button data-min="5">휴식 5분</button><button data-min="15">긴 휴식 15분</button></div><div class="clock" id="clock" role="timer">25:00</div><p class="muted small" id="timerState" role="status">준비되면 시작하세요.</p><div class="progress"><div id="bar"></div></div><div class="row" style="justify-content:center"><button class="primary" id="start">시작하기 ▶</button><button id="reset">초기화 ↺</button></div><p class="small muted" style="margin-top:30px">탭을 열어두면 완료 시 화면과 소리로 알려드려요.</p></section><section class="panel"><div class="row between"><h2 style="margin:0">오늘 할 일</h2><span id="count" class="small muted"></span></div><form id="add" class="row" style="margin-top:25px;flex-wrap:nowrap"><input id="taskInput" style="width:100%;min-width:0" aria-label="새 할 일" placeholder="작은 할 일 하나 추가하기" maxlength="150" required><button class="primary" aria-label="할 일 추가">＋</button></form><div id="tasks"></div><p id="noTasks" class="muted small">아직 할 일이 없어요. 첫 번째 작은 목표를 적어보세요.</p><div style="margin-top:30px;border-top:1px solid var(--line);padding-top:20px" class="row between"><div><div class="eyebrow">Today's focus</div><div class="stat"><span id="sessions">0</span> <span class="small">회 완료</span></div></div><div><div class="eyebrow">Completed</div><div class="stat"><span id="done">0</span> <span class="small">개 해결</span></div></div></div></section></div><p class="quote">“속도보다 중요한 건, 오늘도 한 걸음.”</p><p class="small muted">할 일과 집중 횟수는 이 브라우저에 저장됩니다. 날짜가 바뀌면 집중 횟수가 새로 시작됩니다.</p></main><footer><span>오늘의 몰입 © 2026</span><span>Take a breath. Begin again.</span></footer>''', '''const $=s=>document.querySelector(s);const day=new Date().toLocaleDateString('sv-SE');$('#date').textContent=new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});let tasks=[],sessions=0;try{tasks=JSON.parse(localStorage.getItem('focus-tasks')||'[]');const s=JSON.parse(localStorage.getItem('focus-sessions')||'{}');if(s.day===day)sessions=s.count||0}catch{}function persist(){try{localStorage.setItem('focus-tasks',JSON.stringify(tasks));localStorage.setItem('focus-sessions',JSON.stringify({day,count:sessions}))}catch{}}function render(){const list=$('#tasks');list.replaceChildren();tasks.forEach((t,i)=>{const row=document.createElement('div');row.className='task'+(t.done?' done':'');const check=document.createElement('input');check.type='checkbox';check.checked=t.done;check.setAttribute('aria-label',t.text+' 완료');check.onchange=()=>{t.done=check.checked;persist();render()};const span=document.createElement('span');span.textContent=t.text;const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',t.text+' 삭제');del.onclick=()=>{tasks.splice(i,1);persist();render()};row.append(check,span,del);list.append(row)});$('#noTasks').hidden=tasks.length>0;$('#count').textContent=tasks.filter(t=>t.done).length+' / '+tasks.length;$('#done').textContent=tasks.filter(t=>t.done).length;$('#sessions').textContent=sessions}$('#add').onsubmit=e=>{e.preventDefault();const text=$('#taskInput').value.trim();if(!text)return;tasks.push({text,done:false});$('#taskInput').value='';persist();render()};let total=1500,remaining=total,running=false,end=0,audioCtx;function paint(){const m=Math.floor(remaining/60),s=remaining%60;$('#clock').textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');document.title=(running?$('#clock').textContent+' · ':'')+'오늘의 몰입';$('#bar').style.width=((total-remaining)/total*100)+'%';$('#start').textContent=running?'잠시 멈춤 Ⅱ':'시작하기 ▶'}function complete(){running=false;remaining=0;if(total===1500){sessions++;persist();render()}$('#timerState').textContent=total===1500?'잘했어요! 집중 한 회를 마쳤습니다. 잠시 쉬어가세요.':'휴식 끝! 다시 가볍게 시작해볼까요?';if(audioCtx){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);g.gain.setValueAtTime(.12,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+1);o.frequency.value=660;o.start();o.stop(audioCtx.currentTime+1)}paint()}function tick(){if(!running)return;remaining=Math.max(0,Math.ceil((end-Date.now())/1000));if(!remaining)complete();else paint()}setInterval(tick,250);document.addEventListener('visibilitychange',tick);$('#start').onclick=()=>{if(running){tick();running=false;$('#timerState').textContent='잠시 멈췄어요. 준비되면 이어가세요.'}else{if(!remaining)remaining=total;end=Date.now()+remaining*1000;running=true;$('#timerState').textContent=total===1500?'지금은 오직, 눈앞의 한 가지에.':'숨을 고르고 가볍게 몸을 움직여보세요.';try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume()}catch{}}paint()};$('#reset').onclick=()=>{running=false;remaining=total;$('#timerState').textContent='준비되면 시작하세요.';paint()};document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{running=false;total=+b.dataset.min*60;remaining=total;document.querySelectorAll('[data-min]').forEach(a=>a.classList.toggle('active',a===b));$('#timerState').textContent='준비되면 시작하세요.';paint()});render();paint();''')
print('Built 3 standalone sites')
